{
  "root_cause": "Two independent bugs prevent correct keyboard selection: (1) closeAllLists iterates forward over a live HTMLCollection while removing nodes, skipping every other list and leaving stale suggestion lists in the DOM; (2) navigationController.js adds the outer `navigate` function as the keydown listener instead of the inner `navigation` handler, causing event handling to break down and operate on stale lists.",
  "repair_strategy": "Fix closeAllLists to iterate backwards so all stale lists are removed. Fix navigationController to register the inner `navigation` function as the keydown listener, ensuring arrow-key and Enter handling uses the current suggestion list.",
  "edits": [
    {
      "path": "src/controllers/listController.js",
      "sha256": "e4798fd60aa7911a54bbc686e7886ccf426e29287ae838d434c6bbf763e79ffe",
      "before": "const closeAllLists = (config, element) => {
  // Get all autoComplete lists
  const list = document.getElementsByClassName(config.resultsList.className);
  // Iterate over all autoComplete open lists in the document
  for (let index = 0; index < list.length; index++) {
    // Close all lists
    // except the ones passed as an argument
    if (element !== list[index] && element !== config.inputField) list[index].parentNode.removeChild(list[index]);
  }
  // Remove active descendant
  config.inputField.removeAttribute("aria-activedescendant");
  // Set list to closed
  config.inputField.setAttribute("aria-expanded", false);
};",
      "after": "const closeAllLists = (config, element) => {
  // Get all autoComplete lists
  const list = document.getElementsByClassName(config.resultsList.className);
  // Iterate over all autoComplete open lists in the document
  for (let index = list.length - 1; index >= 0; index--) {
    // Close all lists
    // except the ones passed as an argument
    if (element !== list[index] && element !== config.inputField) list[index].parentNode.removeChild(list[index]);
  }
  // Remove active descendant
  config.inputField.removeAttribute("aria-activedescendant");
  // Set list to closed
  config.inputField.setAttribute("aria-expanded", false);
};"
    },
    {
      "path": "src/controllers/navigationController.js",
      "sha256": "cb38337c041e8e0543c4f7b31666374956d6dc85011604e12ff127c9bf67ddde",
      "before": "const navigate = (config, dataFeedback) => {
  // Reset focus state
  let currentFocus = -1;

  /**
   * Update list item state
   *
   * @param {Object} event - The `keydown` event Object
   * @param {Array <elements>} list - The array of list items
   * @param {Boolean} state - Of the arrow Down/Up
   * @param {Object} config - autoComplete configurations
   *
   */
  const update = (event, list, state, config) => {
    event.preventDefault();
    if (state) {
      // If the arrow DOWN or TAB key is pressed
      // increase the currentFocus
      currentFocus++;
    } else {
      // If the arrow UP or TAB key is pressed
      // decrease the currentFocus
      currentFocus--;
    }
    // and add "active" class to the list item
    addActive(list);
    config.inputField.setAttribute("aria-activedescendant", list[currentFocus].id);
    /**
     * @emits {navigation} Emits Event on results list navigation
     **/
    eventEmitter(
      event.srcElement,
      { event, ...dataFeedback, selection: dataFeedback.results[currentFocus] },
      "navigation"
    );
  };

  /**
   * Remove list item active state
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const removeActive = (list) => {
    // Remove "active" class from all list items
    for (let index = 0; index < list.length; index++) {
      // Remove "active" class from the item
      list[index].removeAttribute("aria-selected");
      // list[index].setAttribute("aria-selected", "false");
      list[index].classList.remove("autoComplete_selected");
    }
  };

  /**
   * Add active state to list item
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const addActive = (list) => {
    // Add "active" class to a list item
    if (!list) return false;
    // Remove "active" class from all list items
    removeActive(list);
    if (currentFocus >= list.length) currentFocus = 0;
    if (currentFocus < 0) currentFocus = list.length - 1;
    // Add "active" class to the item
    list[currentFocus].setAttribute("aria-selected", "true");
    list[currentFocus].classList.add("autoComplete_selected");
  };

  /**
   * List Navigation Function
   *
   * @param {Object} event - The `keydown` event Object
   *
   */
  const navigation = (event) => {
    let list = document.getElementById(config.resultsList.idName);

    if (!list) return config.inputField.removeEventListener("keydown", navigate);

    list = list.getElementsByTagName(config.resultItem.element);

    if (event.keyCode === 27) {
      // If the ESC key is pressed
      // Clear Input value
      config.inputField.value = "";
      // Closes open lists
      closeAllLists(config);
    } else if (event.keyCode === 40 || event.keyCode === 9) {
      // Update list items state
      update(event, list, true, config);
    } else if (event.keyCode === 38 || event.keyCode === 9) {
      // Update list items state
      update(event, list, false, config);
    } else if (event.keyCode === 13) {
      // If the ENTER key is pressed
      // prevent the form from its default behaviour "being submitted"
      event.preventDefault();
      if (currentFocus > -1) {
        // and simulate a click on the selected "active" item
        if (list) list[currentFocus].click();
      }
    }
  };

  config.inputField.addEventListener("keydown", navigate);
};",
      "after": "const navigate = (config, dataFeedback) => {
  // Reset focus state
  let currentFocus = -1;

  /**
   * Update list item state
   *
   * @param {Object} event - The `keydown` event Object
   * @param {Array <elements>} list - The array of list items
   * @param {Boolean} state - Of the arrow Down/Up
   * @param {Object} config - autoComplete configurations
   *
   */
  const update = (event, list, state, config) => {
    event.preventDefault();
    if (state) {
      // If the arrow DOWN or TAB key is pressed
      // increase the currentFocus
      currentFocus++;
    } else {
      // If the arrow UP or TAB key is pressed
      // decrease the currentFocus
      currentFocus--;
    }
    // and add "active" class to the list item
    addActive(list);
    config.inputField.setAttribute("aria-activedescendant", list[currentFocus].id);
    /**
     * @emits {navigation} Emits Event on results list navigation
     **/
    eventEmitter(
      event.srcElement,
      { event, ...dataFeedback, selection: dataFeedback.results[currentFocus] },
      "navigation"
    );
  };

  /**
   * Remove list item active state
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const removeActive = (list) => {
    // Remove "active" class from all list items
    for (let index = 0; index < list.length; index++) {
      // Remove "active" class from the item
      list[index].removeAttribute("aria-selected");
      // list[index].setAttribute("aria-selected", "false");
      list[index].classList.remove("autoComplete_selected");
    }
  };

  /**
   * Add active state to list item
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const addActive = (list) => {
    // Add "active" class to a list item
    if (!list) return false;
    // Remove "active" class from all list items
    removeActive(list);
    if (currentFocus >= list.length) currentFocus = 0;
    if (currentFocus < 0) currentFocus = list.length - 1;
    // Add "active" class to the item
    list[currentFocus].setAttribute("aria-selected", "true");
    list[currentFocus].classList.add("autoComplete_selected");
  };

  /**
   * List Navigation Function
   *
   * @param {Object} event - The `keydown` event Object
   *
   */
  const navigation = (event) => {
    let list = document.getElementById(config.resultsList.idName);

    if (!list) return config.inputField.removeEventListener("keydown", navigation);

    list = list.getElementsByTagName(config.resultItem.element);

    if (event.keyCode === 27) {
      // If the ESC key is pressed
      // Clear Input value
      config.inputField.value = "";
      // Closes open lists
      closeAllLists(config);
    } else if (event.keyCode === 40 || event.keyCode === 9) {
      // Update list items state
      update(event, list, true, config);
    } else if (event.keyCode === 38 || event.keyCode === 9) {
      // Update list items state
      update(event, list, false, config);
    } else if (event.keyCode === 13) {
      // If the ENTER key is pressed
      // prevent the form from its default behaviour "being submitted"
      event.preventDefault();
      if (currentFocus > -1) {
        // and simulate a click on the selected "active" item
        if (list) list[currentFocus].click();
      }
    }
  };

  config.inputField.addEventListener("keydown", navigation);
};"
    }
  ],
  "expected_accessibility_effect": "Stale suggestion lists are fully removed, eliminating duplicate IDs. Keyboard navigation (ArrowDown, ArrowUp, Enter) now operates on the current list only, so the announced aria-selected item matches the committed form value. Screen readers will announce the correct selected option.",
  "functional_risks": [
    "Backward iteration in closeAllLists is safe because removal order does not affect other logic.",
    "Changing the listener from `navigate` to `navigation` aligns with the intended design; no other code depends on the old listener."
  ],
  "verification_requirements": [
    "After the sequence: focus #fruit, type 'b', ArrowDown ×2, type 'l', ArrowDown, Enter, the input value must be 'Blackberry'.",
    "Confirm that no more than one element with ID 'autoComplete_list' exists in the DOM after each interaction.",
    "Verify that ArrowDown and ArrowUp move aria-selected correctly through the filtered list.",
    "Verify that Enter commits the currently highlighted suggestion."
  ]
}
